let match=null,matchBusy=false,matchOffset=0,matchStarted=false,matchEnded=false,matchPlan=[],eventIndex=0;
const soloBegin=begin,soloUpdate=update,soloResult=result,soloToggle=toggle,soloDraw=drawHero;
async function roomApi(action,extra={}){const r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:match?.code,id:match?.id,token:match?.token,...extra})}),d=await r.json();if(!r.ok)throw Error(d.error||'연결 실패');return d}
function matchText(t){$('match-status').textContent=t}
function updateRoomView(d){const id=match.id;match={...match,...d,id};$('room-code').textContent='방 코드: '+match.code;$('room-start').disabled=match.players.length!==2||match.players[0].id!==id||match.status!=='waiting';$('room-start').hidden=match.players[0].id!==id;const me=match.players.find(p=>p.id===id),other=match.players.find(p=>p.id!==id);$('match-scores').textContent=`나 ${me?.score.toLocaleString()||0}점  vs  ${other?other.name+' '+other.score.toLocaleString()+'점':'상대 입장 대기'}`;
if(match.status==='waiting')matchText('같은 코드를 다른 탭에 입력하세요. 두 명이 모이면 방장이 시작합니다.');if(match.status==='closed'&&!matchEnded){matchEnded=true;state='paused';matchText(d.reason||'방이 종료되었습니다.');panel('대전 연결 종료','대전판에서 나가기 후 새 방을 만들어 주세요.','싱글로 돌아가기')}if(match.status==='finished'&&!matchEnded){matchEnded=true;state='over';overAt=Date.now();panel(match.winner==='draw'?'무승부!':match.winner===id?'승리! 🏆':'다음엔 이길 수 있어요!','최종 점수는 위 대전판에서 확인하세요.','싱글로 돌아가기');matchText('대전 종료 · 나가기 후 새 경기를 시작하세요.')}}
async function enterRoom(action){if(match)return;try{const d=await roomApi(action,{name:$('match-name').value,code:$('join-code').value.trim().toUpperCase()});match=d;matchOffset=d.now-Date.now();matchStarted=matchEnded=false;matchPlan=[];eventIndex=0;if(state==='playing')soloToggle();$('room-actions').hidden=true;$('room-controls').hidden=false;updateRoomView(d)}catch(e){matchText(e.message)}}
$('room-create').onclick=()=>enterRoom('create');$('room-join').onclick=()=>enterRoom('join');$('room-start').onclick=async()=>{try{updateRoomView(await roomApi('start'))}catch(e){matchText(e.message)}};
async function leaveRoom(){if(match)try{await roomApi('leave')}catch{}match=null;matchStarted=matchEnded=false;matchPlan=[];$('room-actions').hidden=false;$('room-controls').hidden=true;matchText('닉네임을 정하고 방을 만들거나 6자리 코드로 입장하세요.');$('match-scores').textContent='';state='ready';panel('싱글 플레이','스페이스바나 화면 터치로 점프하세요.','달리기 시작 →')}
$('room-leave').onclick=leaveRoom;
begin=function(){if(match){if(matchEnded){leaveRoom();return}matchText('대전판에서 두 명이 모이면 방장이 시작해 주세요.');return}soloBegin()};toggle=function(){if(match){matchText('실시간 대전은 일시정지할 수 없습니다.');return}soloToggle()};
result=function(clear){if(!match){soloResult(clear);return}state='over';cleared=clear;overAt=Date.now();panel(clear?'완주! 상대를 기다려요':'탈락! 상대를 기다려요',`내 최종 점수 ${score.toLocaleString()}점`,'결과 대기 중')};
const trackDistance=t=>{let d=0;for(let s=0;s<4;s++)d+=Math.max(0,Math.min(30,t-s*30))*stageSpeeds[s];return d};
update=function(dt){if(!match){soloUpdate(dt);return}if(!matchStarted||matchEnded||state!=='playing')return;const target=Math.min(120,Math.max(0,(Date.now()+matchOffset-match.startAt)/1000));let steps=0;while(time+1/60<=target&&state==='playing'&&steps++<240){const step=1/60,old=trackDistance(time),beforeCoins=new Set(coins);spawn=coinTimer=specialTimer=itemTimer=1e9;soloUpdate(step);if(boost>0)for(const c of coins)if(!beforeCoins.has(c)&&c.seed===undefined&&['normal','star'].includes(c.type))c.type=Math.floor(time/.075)%5===0?'star':'normal';const current=trackDistance(time),delta=speed*step-(current-old);scroll=current;for(const o of obstacles)o.x+=delta;for(const c of coins)c.x+=delta;while(eventIndex<matchPlan.length&&matchPlan[eventIndex].at<=time){const e=matchPlan[eventIndex++],x=W+70+(e.offset||0)-(current-trackDistance(e.at));if(e.kind==='obstacle')obstacles.push({x,w:e.w,h:e.h,type:e.type,variant:e.variant,tall:e.h>100,phase:0});else coins.push(liftPickup({x,y:e.y,type:e.type,seed:eventIndex*.7}))}}if(target>=120&&state==='playing'&&time>119.98)soloUpdate(120-time+.000001)};
drawHero=function(){const o=match?.players.find(p=>p.id!==match.id);if(matchStarted&&o){ctx.save();ctx.globalAlpha=.4;const x=hero.x+85;if(heroSheetReady()){ctx.save();ctx.translate(x+29,o.y);drawSheetFrame(o.done?5:o.boost>0?4:o.y<G-1?2:Math.floor(time*12)%2,0);ctx.restore()}else ellipse(x+29,o.y-40,27,35,'#a9a4df',true);ctx.fillStyle='#735f92';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText(o.name+(o.done?' · 종료':''),x+29,o.y-85);ctx.restore()}soloDraw()};
setInterval(async()=>{if(!match||matchBusy)return;matchBusy=true;try{const d=await roomApi('tick',{needPlan:!matchStarted,player:matchStarted?{score,y:hero.y,jumps:hero.jumps,boost,hearts,done:state==='over',clear:cleared,pose:heroMotion()}:undefined});updateRoomView(d);matchOffset=d.now-Date.now();if(d.status==='running'&&!matchStarted){if(d.events)matchPlan=d.events;const left=(d.startAt-Date.now()-matchOffset)/1000;if(left>0){matchText(`동시 출발까지 ${Math.ceil(left)}초!`);return}matchStarted=true;soloBegin();matchText('대전 중 · 공통 코스 / 피버 중에도 코스 속도는 동일');}if(matchStarted&&!matchEnded&&state==='playing')update(0)}catch(e){matchText('연결 확인 중: '+e.message)}finally{matchBusy=false}},100);
$('multiplayer').addEventListener('keydown',e=>e.stopPropagation());
